package com.tanerinal.education.service;
import com.fasterxml.jackson.databind.ObjectMapper;import com.tanerinal.education.domain.PaymentChannel;import com.tanerinal.education.security.PaymentSigning;import io.github.resilience4j.bulkhead.annotation.Bulkhead;import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker;import io.github.resilience4j.retry.annotation.Retry;import java.math.BigDecimal;import java.util.Map;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.MediaType;import org.springframework.stereotype.Component;import org.springframework.web.client.RestClient;
@Component public class PaymentGatewayClient{private final RestClient client;private final ObjectMapper mapper;private final String baseUrl;public PaymentGatewayClient(RestClient.Builder b,ObjectMapper m,@Value("${education.payment-platform.base-url:http://localhost:18082}")String u){client=b.build();mapper=m;baseUrl=u;}@Retry(name="paymentPlatform")@CircuitBreaker(name="paymentPlatform")@Bulkhead(name="paymentPlatform")public Result create(String no,PaymentChannel channel,String subject,BigDecimal amount,String currency,String scenario){try{String body=mapper.writeValueAsString(Map.of("merchantRequestNo",no,"channel",channel.name(),"subject",subject,"amount",amount,"currency",currency,"faultScenario",scenario));String path="/api/channel/transactions";var c=PaymentSigning.credentials(channel);return client.post().uri(baseUrl+path).contentType(MediaType.APPLICATION_JSON).headers(h->PaymentSigning.apply(h,"POST",path,body,c.appId(),c.secret())).body(body).retrieve().body(Result.class);}catch(Exception e){throw new BusinessRuleException("Payment platform unavailable: "+e.getMessage());}}public record Result(String channelTransactionNo,String status,String actionType,String checkoutUrl,String qrPayload,java.time.LocalDateTime expiresAt){public java.time.Instant expiresInstant(){return expiresAt.toInstant(java.time.ZoneOffset.UTC);}}}
